from decimal import Decimal, getcontext
from collections import defaultdict, Counter
import csv, json, os
getcontext().prec = 28
base='/app'

def D(x):
    return Decimal(str(x))

def load_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

def load_json(path):
    with open(path) as f:
        return json.load(f)

# load data
current_week = load_json(base+'/data/current_week.json')['week']
state4 = load_json(base+'/state/week4_state.json')
state2 = load_json(base+'/state/week2_state.json')
step3 = load_csv(base+'/submissions/step3_replan.csv')
step2 = load_csv(base+'/submissions/step2_replan.csv')

# master data
weeks = {int(r['week']) for r in load_csv(base+'/data/weeks.csv')}
products = {r['product_id']: r for r in load_csv(base+'/data/products.csv')}
materials = {r['material_id']: r for r in load_csv(base+'/data/materials.csv')}
customers = {r['customer_id']: r for r in load_csv(base+'/data/customers.csv')}
warehouses = {r['dc_id']: r for r in load_csv(base+'/data/warehouses.csv')}
plants = {r['plant_id']: r for r in load_csv(base+'/data/plants.csv')}
plant_products = {(r['plant_id'], r['product_id']): r for r in load_csv(base+'/data/plant_products.csv')}
plant_to_dc = {(r['plant_id'], r['dc_id']): r for r in load_csv(base+'/data/plant_to_dc_lanes.csv')}
dc_to_customer = {(r['dc_id'], r['customer_id']): r for r in load_csv(base+'/data/dc_to_customer_lanes.csv')}
dc_transfer = {(r['from_dc'], r['to_dc']): r for r in load_csv(base+'/data/dc_transfer_lanes.csv')}
safety = {(r['dc_id'], r['product_id']): D(r['safety_stock_tons']) for r in load_csv(base+'/data/safety_stock.csv')}
bom = defaultdict(dict)
for r in load_csv(base+'/data/bom.csv'):
    bom[r['product_id']][r['material_id']] = D(r['tons_material_per_ton_product'])
material_supply = {(int(r['week']), r['plant_id'], r['material_id']): r for r in load_csv(base+'/data/material_supply.csv')}
pipeline = load_csv(base+'/data/pipeline_receipts.csv')
pol = load_csv(base+'/data/planning_policies.csv')[0]
reserve_mult = D(pol['reserve_multiplier_next_week_demand'])
mat_discount = D(pol['material_robust_discount'])
frozen = load_csv(base+'/data/frozen_commitment_policy.csv')
demand = {(int(r['week']), r['customer_id'], r['product_id']): D(r['demand_tons']) for r in load_csv(base+'/data/demand.csv')}

# helpers

def parse_plan(rows):
    parsed=[]
    for i,r in enumerate(rows, start=2):
        rr=dict(r)
        rr['rownum']=i
        rr['week_i']=int(r['week'])
        rr['qty']=D(r['quantity'])
        parsed.append(rr)
    return parsed

step3p=parse_plan(step3)
step2p=parse_plan(step2)

# summary by exact key
for label, rows in [('step3', step3p), ('step2', step2p)]:
    print('PLAN', label)
    print(' rows', len(rows))
    v=Counter(r['variable'] for r in rows)
    print(' vars', v)
    print()

# schema/domain checks
viol=[]

supported={'setup','produce_regular','produce_overtime','ship_plant_dc','ship_dc_customer','transfer_dc','inventory','shortage','emergency_material','validated_shipper'}
for r in step3p:
    key=(r['variable'],r['week'],r['item'],r['from'],r['to'])
    if r['variable'] not in supported:
        viol.append(('schema',r,'unsupported variable'))
    if r['week_i'] not in weeks or r['week_i'] < current_week:
        viol.append(('time',r,f'invalid week {r[\"week_i\"]}'))
    if r['qty'] < 0:
        viol.append(('schema',r,'negative quantity'))
    if r['qty'] == 0:
        viol.append(('schema',r,'zero quantity row exported'))
    var=r['variable']
    if var=='setup':
        if r['to']"'!='"'' or r['from'] not in plants or r['item'] not in products:
            viol.append(('schema',r,'setup nullability/domain'))
        if (r['from'],r['item']) not in plant_products:
            viol.append(('domain',r,'setup infeasible plant-product'))
        if r['qty'] not in (D('0'),D('1')):
            viol.append(('schema',r,'setup not binary'))
    elif var in ('produce_regular','produce_overtime'):
        if r['to']"'!='"'' or r['from'] not in plants or r['item'] not in products:
            viol.append(('schema',r,'production nullability/domain'))
        if (r['from'],r['item']) not in plant_products:
            viol.append(('domain',r,'production infeasible plant-product'))
    elif var=='ship_plant_dc':
        if r['from'] not in plants or r['to'] not in warehouses or r['item'] not in products:
            viol.append(('domain',r,'plant-dc id domain'))
        if (r['from'],r['to']) not in plant_to_dc:
            viol.append(('domain',r,'plant-dc lane missing'))
    elif var=='ship_dc_customer':
        if r['from'] not in warehouses or r['to'] not in customers or r['item'] not in products:
            viol.append(('domain',r,'dc-customer id domain'))
        if (r['from'],r['to']) not in dc_to_customer:
            viol.append(('domain',r,'dc-customer lane missing'))
    elif var=='transfer_dc':
        if r['from'] not in warehouses or r['to'] not in warehouses or r['item'] not in products:
            viol.append(('domain',r,'transfer id domain'))
        if (r['from'],r['to']) not in dc_transfer:
            viol.append(('domain',r,'transfer lane missing'))
    elif var=='inventory':
        if r['to']"'!='"'' or r['from'] not in warehouses or r['item'] not in products:
            viol.append(('domain',r,'inventory nullability/domain'))
    elif var=='shortage':
        if r['to']"'!='"'' or r['from'] not in customers or r['item'] not in products:
            viol.append(('domain',r,'shortage nullability/domain'))
    elif var=='emergency_material':
        if r['from']"'!='"'external' or r['to'] not in plants or r['item'] not in materials:
            viol.append(('domain',r,'emergency material domain'))
    elif var=='validated_shipper':
        viol.append(('schema',r,'validated_shipper not allowed without policy'))

# duplicates
ctr=Counter((r['variable'],r['week'],r['item'],r['from'],r['to']) for r in step3p)
for key,count in ctr.items():
    if count>1:
        viol.append(('schema',key,f'duplicate key x{count}'))

# aggregate quantities by key

def keydict(rows):
    d=defaultdict(Decimal)
    rowmap={}
    for r in rows:
        key=(r['variable'],r['week_i'],r['item'],r['from'],r['to'])
        d[key]+=r['qty']
        rowmap[key]=r
    return d,rowmap
s3,s3row=keydict(step3p)
s2,s2row=keydict(step2p)

# demand balance/service
for (w,c,p),dem in demand.items():
    if w < current_week:
        continue
    shipped = sum(r['qty'] for r in step3p if r['variable']=='ship_dc_customer' and r['week_i']==w and r['to']==c and r['item']==p)
    shortage = s3.get(('shortage',w,p,c,''), Decimal('0'))
    total = shipped + shortage
    if abs(total-dem) > Decimal('0.0001'):
        viol.append(('conservation', ('demand',w,c,p), f'delivered+shortage {total} "'!= demand {dem}'"'))
    min_sr = D(customers[c]['min_service_rate'])
    req = dem * min_sr
    if shipped + Decimal('0.0001') < req:
        viol.append(('capacity', ('service',w,c,p), f'shipped {shipped} < min service {req}'))

# setup/production/run sizes/outbound support/hours/materials
for w in range(current_week, 11):
    for plant in plants:
        reg_hours=Decimal('0'); ot_hours=Decimal('0'); setup_hours=Decimal('0')
        for p in products:
            pr = s3.get(('produce_regular',w,p,plant,''), Decimal('0'))
            po = s3.get(('produce_overtime',w,p,plant,''), Decimal('0'))
            setup = s3.get(('setup',w,p,plant,''), Decimal('0'))
            total = pr + po
            if total > 0 and setup < Decimal('0.9999'):
                viol.append(('readiness', ('prod',w,plant,p), f'production {total} without setup'))
            if (plant,p) in plant_products:
                pp=plant_products[(plant,p)]
                tph=D(pp['tons_per_hour'])
                reg_hours += pr / tph
                ot_hours += po / tph
                setup_hours += setup * D(pp['setup_hours'])
                if total > 0:
                    if total + Decimal('0.0001') < D(pp['min_run_tons']):
                        viol.append(('ramp', ('run_min',w,plant,p), f'production {total} < min run {pp[\"min_run_tons\"]}'))
                    if total - Decimal('0.0001') > D(pp['max_weekly_tons']):
                        viol.append(('capacity', ('run_max',w,plant,p), f'production {total} > max weekly {pp[\"max_weekly_tons\"]}'))
                ship_out = sum(r['qty'] for r in step3p if r['variable']=='ship_plant_dc' and r['week_i']==w and r['from']==plant and r['item']==p)
                if ship_out - total > Decimal('0.0001'):
                    viol.append(('conservation', ('plant_ship_support',w,plant,p), f'shipments {ship_out} > same-week production {total}'))
        if reg_hours - D(plants[plant]['regular_hours']) > Decimal('0.0001'):
            viol.append(('capacity', ('regular_hours',w,plant), f'{reg_hours} > {plants[plant][\"regular_hours\"]}'))
        if ot_hours - D(plants[plant]['overtime_hours']) > Decimal('0.0001'):
            viol.append(('capacity', ('overtime_hours',w,plant), f'{ot_hours} > {plants[plant][\"overtime_hours\"]}'))
        if setup_hours - D(plants[plant]['weekly_setup_team_hours']) > Decimal('0.0001'):
            viol.append(('nonoverlap', ('setup_hours',w,plant), f'{setup_hours} > {plants[plant][\"weekly_setup_team_hours\"]}'))
        # material balances
        for m in materials:
            cons=Decimal('0')
            for p in products:
                total=s3.get(('produce_regular',w,p,plant,''), Decimal('0'))+s3.get(('produce_overtime',w,p,plant,''), Decimal('0'))
                cons += total * bom[p].get(m, Decimal('0'))
            regular = D(material_supply[(w,plant,m)]['regular_available_tons']) * mat_discount if (w,plant,m) in material_supply else Decimal('0')
            emergency = s3.get(('emergency_material',w,m,'external',plant), Decimal('0'))
            if cons - (regular + emergency) > Decimal('0.0001'):
                viol.append(('capacity', ('material',w,plant,m), f'use {cons} > discounted regular+emergency {regular+emergency}'))
            cap = D(material_supply[(w,plant,m)]['emergency_cap_tons']) if (w,plant,m) in material_supply else Decimal('0')
            if emergency - cap > Decimal('0.0001'):
                viol.append(('capacity', ('emergency_cap',w,plant,m), f'emergency {emergency} > cap {cap}'))

# lane capacities
for w in range(current_week,11):
    for lane,dat in plant_to_dc.items():
        total=sum(r['qty'] for r in step3p if r['variable']=='ship_plant_dc' and r['week_i']==w and r['from']==lane[0] and r['to']==lane[1])
        cap=D(dat['weekly_capacity_tons'])
        if total-cap > Decimal('0.0001'):
            viol.append(('capacity', ('plant_lane',w)+lane, f'{total} > {cap}'))
    for lane,dat in dc_to_customer.items():
        total=sum(r['qty'] for r in step3p if r['variable']=='ship_dc_customer' and r['week_i']==w and r['from']==lane[0] and r['to']==lane[1])
        cap=D(dat['weekly_capacity_tons'])
        if total-cap > Decimal('0.0001'):
            viol.append(('capacity', ('cust_lane',w)+lane, f'{total} > {cap}'))
    for lane,dat in dc_transfer.items():
        total=sum(r['qty'] for r in step3p if r['variable']=='transfer_dc' and r['week_i']==w and r['from']==lane[0] and r['to']==lane[1])
        cap=D(dat['weekly_capacity_tons'])
        if total-cap > Decimal('0.0001'):
            viol.append(('capacity', ('transfer_lane',w)+lane, f'{total} > {cap}'))

# inventory balances and reserves
# pipeline lookup
pipe_prod=defaultdict(Decimal)
pipe_mat=defaultdict(Decimal)
for r in pipeline:
    if r['receipt_type']=='product':
        pipe_prod[(int(r['week']), r['item'], r['to'])] += D(r['quantity'])
    else:
        pipe_mat[(int(r['week']), r['item'], r['to'])] += D(r['quantity'])
# add pipeline material to capacity? likely yes regular or extra source not optional; public says incorporate into material balance. Let's note separately later maybe.
# check if material receipt needed to restore feasibility maybe maybe should be included. For now current material check without pipeline may overstate violation at FILL_EAST week4 COLD_PACK; need include pipeline receipts.
viol2=[]
for entry in list(viol):
    if entry[0]=='capacity' and isinstance(entry[1], tuple) and entry[1][0]=='material':
        family,key,msg=entry
        _,w,plant,m=key
        # recompute with pipeline material
        cons=Decimal('0')
        for p in products:
            total=s3.get(('produce_regular',w,p,plant,''), Decimal('0'))+s3.get(('produce_overtime',w,p,plant,''), Decimal('0'))
            cons += total * bom[p].get(m, Decimal('0'))
        regular = D(material_supply[(w,plant,m)]['regular_available_tons']) * mat_discount if (w,plant,m) in material_supply else Decimal('0')
        emergency = s3.get(('emergency_material',w,m,'external',plant), Decimal('0'))
        receipt = pipe_mat.get((w,m,plant), Decimal('0'))
        if cons - (regular+emergency+receipt) <= Decimal('0.0001'):
            continue
    viol2.append(entry)
viol=viol2

state_inv={(tuple(k.split('|'))): D(v) for k,v in state4['inventory'].items()}
for w in range(current_week,11):
    for dc in warehouses:
        for p in products:
            start = state_inv[(dc,p)] if w==current_week else s3.get(('inventory',w-1,p,dc,''), Decimal('0'))
            inbound = sum(r['qty'] for r in step3p if r['variable']=='ship_plant_dc' and r['week_i']==w and r['to']==dc and r['item']==p)
            tin = sum(r['qty'] for r in step3p if r['variable']=='transfer_dc' and r['week_i']==w and r['to']==dc and r['item']==p)
            tout = sum(r['qty'] for r in step3p if r['variable']=='transfer_dc' and r['week_i']==w and r['from']==dc and r['item']==p)
            cust = sum(r['qty'] for r in step3p if r['variable']=='ship_dc_customer' and r['week_i']==w and r['from']==dc and r['item']==p)
            pipe = pipe_prod[(w,p,dc)]
            end = s3.get(('inventory',w,p,dc,''), Decimal('0'))
            lhs = start + inbound + tin + pipe - tout - cust
            if abs(lhs-end) > Decimal('0.00011'):
                viol.append(('conservation', ('inventory_balance',w,dc,p), f'computed {lhs} "'!= inventory row {end}'"'))
            if end < -Decimal('0.0001'):
                viol.append(('inventory', ('nonnegative',w,dc,p), f'{end} < 0'))
            # reserve req
            if w < max(weeks):
                region = warehouses[dc]['region']
                next_dem = sum(d for (ww,c,pp),d in demand.items() if ww==w+1 and pp==p and customers[c]['region']==region)
            else:
                next_dem = Decimal('0')
            req = safety[(dc,p)] + reserve_mult * next_dem
            if end + Decimal('0.0001') < req:
                viol.append(('reserve', ('reserve',w,dc,p), f'inventory {end} < safety+reserve {req}'))
    total_by_dc=defaultdict(Decimal)
    for dc in warehouses:
        total=sum(s3.get(('inventory',w,p,dc,''), Decimal('0')) for p in products)
        if total - D(warehouses[dc]['capacity_tons']) > Decimal('0.0001'):
            viol.append(('capacity', ('warehouse',w,dc), f'{total} > {warehouses[dc][\"capacity_tons\"]}'))

# state transition validate step2 from week2_state through week3
s2state={(tuple(k.split('|'))): D(v) for k,v in state2['inventory'].items()}
for w in [2,3]:
    for dc in warehouses:
        for p in products:
            start = s2state[(dc,p)] if w==2 else s2.get(('inventory',w-1,p,dc,''), Decimal('0'))
            inbound = sum(r['qty'] for r in step2p if r['variable']=='ship_plant_dc' and r['week_i']==w and r['to']==dc and r['item']==p)
            tin = sum(r['qty'] for r in step2p if r['variable']=='transfer_dc' and r['week_i']==w and r['to']==dc and r['item']==p)
            tout = sum(r['qty'] for r in step2p if r['variable']=='transfer_dc' and r['week_i']==w and r['from']==dc and r['item']==p)
            cust = sum(r['qty'] for r in step2p if r['variable']=='ship_dc_customer' and r['week_i']==w and r['from']==dc and r['item']==p)
            pipe = pipe_prod[(w,p,dc)]
            end = s2.get(('inventory',w,p,dc,''), Decimal('0'))
            lhs = start + inbound + tin + pipe - tout - cust
            if abs(lhs-end) > Decimal('0.00011'):
                viol.append(('frozen', ('state_transition',w,dc,p), f'computed {lhs} "'!= prior artifact inventory {end}'"'))
# compare week3 end to week4 state
for dc in warehouses:
    for p in products:
        prev = s2.get(('inventory',3,p,dc,''), Decimal('0'))
        st = state_inv[(dc,p)]
        if abs(prev-st) > Decimal('0.00011'):
            viol.append(('frozen', ('state_match',4,dc,p), f'step2 week3 inventory {prev} "'!= week4 state {st}'"'))

# frozen policies, treating omitted baseline as zero on exact key space implied by variable
hospital_customers={c for c,r in customers.items() if r['segment']=='hospital'}
for polr in frozen:
    var=polr['variable']; sw=int(polr['start_week']); ew=int(polr['end_week']); minf=D(polr['minimum_fraction']); maxf=D(polr['maximum_fraction']); filt=polr['customer_filter']
    for w in range(sw, ew+1):
        if var=='ship_plant_dc':
            for p in products:
                for plant,dc in plant_to_dc:
                    prev=s2.get((var,w,p,plant,dc), Decimal('0'))
                    new=s3.get((var,w,p,plant,dc), Decimal('0'))
                    if new + Decimal('0.0001') < minf*prev or new - Decimal('0.0001') > maxf*prev:
                        viol.append(('frozen', ('freeze',var,w,p,plant,dc), f'new {new} outside [{minf*prev}, {maxf*prev}] from prior {prev}'))
        elif var=='transfer_dc':
            for p in products:
                for dc1,dc2 in dc_transfer:
                    prev=s2.get((var,w,p,dc1,dc2), Decimal('0'))
                    new=s3.get((var,w,p,dc1,dc2), Decimal('0'))
                    if new + Decimal('0.0001') < minf*prev or new - Decimal('0.0001') > maxf*prev:
                        viol.append(('frozen', ('freeze',var,w,p,dc1,dc2), f'new {new} outside [{minf*prev}, {maxf*prev}] from prior {prev}'))
        elif var=='ship_dc_customer':
            custs = hospital_customers if filt=='hospital' else customers.keys()
            for p in products:
                for dc,c in dc_to_customer:
                    if c not in custs:
                        continue
                    prev=s2.get((var,w,p,dc,c), Decimal('0'))
                    new=s3.get((var,w,p,dc,c), Decimal('0'))
                    if new + Decimal('0.0001') < minf*prev or new - Decimal('0.0001') > maxf*prev:
                        viol.append(('frozen', ('freeze',var,w,p,dc,c), f'new {new} outside [{minf*prev}, {maxf*prev}] from prior {prev}'))

# objective recompute (no comparison target, just total)
obj=Decimal('0')
terms=defaultdict(Decimal)
for r in step3p:
    w=r['week_i']; q=r['qty']; var=r['variable']
    if var=='setup':
        terms['setup_cost'] += q * D(plant_products[(r['from'],r['item'])]['setup_cost'])
    elif var=='produce_regular':
        terms['regular_prod'] += q * D(plant_products[(r['from'],r['item'])]['regular_cost_per_ton'])
    elif var=='produce_overtime':
        terms['overtime_prod'] += q * D(plant_products[(r['from'],r['item'])]['overtime_cost_per_ton'])
    elif var=='ship_plant_dc':
        terms['plant_dc_transport'] += q * D(plant_to_dc[(r['from'],r['to'])]['cost_per_ton'])
    elif var=='ship_dc_customer':
        terms['dc_cust_transport'] += q * D(dc_to_customer[(r['from'],r['to'])]['cost_per_ton'])
        terms['dc_handling'] += q * D(warehouses[r['from']]['handling_cost_per_ton'])
    elif var=='transfer_dc':
        terms['dc_transfer_transport'] += q * D(dc_transfer[(r['from'],r['to'])]['cost_per_ton'])
    elif var=='inventory':
        terms['holding'] += q * D(products[r['item']]['hold_cost_per_ton_week'])
    elif var=='shortage':
        pen = D(products[r['item']]['strategic_shortage_penalty_per_ton']) if customers[r['from']]['segment'] in {'hospital','public_health'} else D(products[r['item']]['shortage_penalty_per_ton'])
        terms['shortage'] += q * pen
    elif var=='emergency_material':
        terms['emergency_material'] += q * D(materials[r['item']]['emergency_unit_cost'])
# replan change penalty vs step2 on overlapping weeks for relevant vars and full key space of union
penalty=D(pol['replan_change_penalty_per_ton'])
for var in ['produce_regular','produce_overtime','ship_plant_dc','ship_dc_customer','transfer_dc']:
    keys={k for k in s2 if k[0]==var and k[1]>=current_week} | {k for k in s3 if k[0]==var and k[1]>=current_week}
    for k in keys:
        terms['replan_change'] += penalty * abs(s3.get(k,Decimal('0')) - s2.get(k,Decimal('0')))
print('violation count', len(viol))
counts=Counter(v[0] for v in viol)
print('family counts', counts)
for fam,cnt in counts.items():
    print('\\nFAMILY', fam, cnt)
    for v in viol:
        if v[0]==fam:
            print(v)
            cnt-=1
            if cnt<=0 or cnt<counts[fam]-10:
                break
print('\\nObjective terms:')
for k,v in terms.items():
    print(k, v)
print('total', sum(terms.values(), Decimal('0')))
PY"

/bin/bash -lc "python - <<'PY'
from decimal import Decimal, getcontext
from collections import defaultdict, Counter
import csv, json, os
getcontext().prec = 28
base='/app'

def D(x):
    return Decimal(str(x))

def load_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

def load_json(path):
    with open(path) as f:
        return json.load(f)

# load data
current_week = load_json(base+'/data/current_week.json')['week']
state4 = load_json(base+'/state/week4_state.json')
state2 = load_json(base+'/state/week2_state.json')
step3 = load_csv(base+'/submissions/step3_replan.csv')
step2 = load_csv(base+'/submissions/step2_replan.csv')

# master data
weeks = {int(r['week']) for r in load_csv(base+'/data/weeks.csv')}
products = {r['product_id']: r for r in load_csv(base+'/data/products.csv')}
materials = {r['material_id']: r for r in load_csv(base+'/data/materials.csv')}
customers = {r['customer_id']: r for r in load_csv(base+'/data/customers.csv')}
warehouses = {r['dc_id']: r for r in load_csv(base+'/data/warehouses.csv')}
plants = {r['plant_id']: r for r in load_csv(base+'/data/plants.csv')}
plant_products = {(r['plant_id'], r['product_id']): r for r in load_csv(base+'/data/plant_products.csv')}
plant_to_dc = {(r['plant_id'], r['dc_id']): r for r in load_csv(base+'/data/plant_to_dc_lanes.csv')}
